    cred_hold = _text(_value(row, "CRED_HOLD")) or "N"
    create_dt = _text(_value(row, "CREATE_DT")) or "00000000"

    return (
        _fixed(_value(row, "ACCT_ID"), 10)
        + _fixed(_value(row, "ACCT_NM"), 40)
        + _fixed(_value(row, "REGION_CD"), 3)
        + _zpad(ann_rev, 15)
        + cred_hold
        + create_dt
    )
